import{_ as t,o as n,c as e,ag as s}from"./chunks/framework.-Wrcbzkw.js";const g=JSON.parse('{"title":"D2C - Design to Code 平台","description":"","frontmatter":{},"headers":[],"relativePath":"project/前端/D2C设计转代码平台.md","filePath":"project/前端/D2C设计转代码平台.md","lastUpdated":1781363231000}'),l={name:"project/前端/D2C设计转代码平台.md"};function i(p,a,r,o,d,h){return n(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="d2c-design-to-code-平台" tabindex="-1">D2C - Design to Code 平台 <a class="header-anchor" href="#d2c-design-to-code-平台" aria-label="Permalink to &quot;D2C - Design to Code 平台&quot;">​</a></h1><h2 id="项目简介" tabindex="-1">项目简介 <a class="header-anchor" href="#项目简介" aria-label="Permalink to &quot;项目简介&quot;">​</a></h2><p>D2C 是一个基于 LangChain 多 Agent 架构的自动化代码生成平台，能够将 Figma 设计稿自动转换为可运行的前端代码。</p><p><strong>核心流程</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Figma URL → 5个AI Agent协同工作 → 可运行的前端代码</span></span></code></pre></div><hr><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>技术</th></tr></thead><tbody><tr><td>前端</td><td>Next.js 14 + React 18 + TypeScript + Tailwind CSS</td></tr><tr><td>后端</td><td>FastAPI (Python)</td></tr><tr><td>AI 框架</td><td>LangChain (Agent / Tool / Memory / Chain)</td></tr><tr><td>LLM</td><td>DeepSeek-V3 / Qwen2.5-7B (SiliconFlow)</td></tr><tr><td>Embedding</td><td>BGE-M3 (SiliconFlow)</td></tr><tr><td>向量数据库</td><td>ChromaDB</td></tr></tbody></table><hr><h2 id="_5-agent-协同流水线" tabindex="-1">5 Agent 协同流水线 <a class="header-anchor" href="#_5-agent-协同流水线" aria-label="Permalink to &quot;5 Agent 协同流水线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────┐    ┌─────────┐    ┌─────────┐    ┌─────────┐    ┌─────────┐</span></span>
<span class="line"><span>│ Agent 1 │───→│ Agent 2 │───→│ Agent 3 │───→│ Agent 4 │───→│ Agent 5 │</span></span>
<span class="line"><span>│ 数据清洗 │    │ 结构转换 │    │ 知识检索 │    │ 代码生成 │    │ 测试验证 │</span></span>
<span class="line"><span>└─────────┘    └─────────┘    └─────────┘    └─────────┘    └─────────┘</span></span></code></pre></div><h3 id="agent-1-数据清洗" tabindex="-1">Agent 1: 数据清洗 <a class="header-anchor" href="#agent-1-数据清洗" aria-label="Permalink to &quot;Agent 1: 数据清洗&quot;">​</a></h3><p><strong>职责</strong>：清洗 Figma 原始 JSON，去掉前端渲染不需要的冗余字段</p><p><strong>实现方式</strong>：纯 Python 代码，不使用 LLM</p><p><strong>处理内容</strong>：</p><ul><li>移除内部 ID、版本号、编辑时间等元数据</li><li>过滤 <code>visible: false</code> 的隐藏图层</li><li>将 Figma RGBA 颜色转换为 CSS hex/rgba</li><li>将 Figma 自动布局映射为 Flexbox</li><li>将阴影效果转换为 CSS box-shadow</li></ul><h3 id="agent-2-结构化转换" tabindex="-1">Agent 2: 结构化转换 <a class="header-anchor" href="#agent-2-结构化转换" aria-label="Permalink to &quot;Agent 2: 结构化转换&quot;">​</a></h3><p><strong>职责</strong>：将清洗后的 Figma 数据转换为组件 DSL</p><p><strong>实现方式</strong>：纯 Python 规则引擎，不使用 LLM</p><p><strong>转换规则</strong>：</p><table tabindex="0"><thead><tr><th>Figma 节点</th><th>DSL 输出</th></tr></thead><tbody><tr><td>FRAME</td><td>Container/Page 组件</td></tr><tr><td>TEXT</td><td>Text/Label 组件</td></tr><tr><td>RECTANGLE</td><td>Box/Div 组件</td></tr><tr><td>COMPONENT/INSTANCE</td><td>对应业务组件</td></tr></tbody></table><h3 id="agent-3-知识检索" tabindex="-1">Agent 3: 知识检索 <a class="header-anchor" href="#agent-3-知识检索" aria-label="Permalink to &quot;Agent 3: 知识检索&quot;">​</a></h3><p><strong>职责</strong>：从 ChromaDB 知识库检索组件库文档</p><p><strong>实现方式</strong>：直接用 Python 代码操作 ChromaDB，不依赖 LLM</p><p><strong>检索流程</strong>：</p><ol><li>解析 DSL，收集所有组件类型</li><li>对每个组件类型构造查询</li><li>调用 ChromaDB 检索相关文档</li><li>将文档附加到 DSL 的 <code>componentDocs</code> 字段</li></ol><h3 id="agent-4-代码生成" tabindex="-1">Agent 4: 代码生成 <a class="header-anchor" href="#agent-4-代码生成" aria-label="Permalink to &quot;Agent 4: 代码生成&quot;">​</a></h3><p><strong>职责</strong>：根据 DSL + 组件文档生成完整的页面代码</p><p><strong>实现方式</strong>：使用 DeepSeek-V3 LLM 生成代码</p><p><strong>生成规则</strong>：</p><ul><li>严格按照 DSL 组件结构排列</li><li>优先使用组件库组件</li><li>使用 Tailwind CSS 暗色主题</li><li>Vue: template + script + style 完整文件</li><li>React: TSX + TypeScript 类型定义</li></ul><h3 id="agent-5-测试验证" tabindex="-1">Agent 5: 测试验证 <a class="header-anchor" href="#agent-5-测试验证" aria-label="Permalink to &quot;Agent 5: 测试验证&quot;">​</a></h3><p><strong>职责</strong>：验证代码质量并自动修复问题</p><p><strong>实现方式</strong>：AST 静态分析 + LLM 深度审查</p><p><strong>检查项目</strong>：</p><ul><li>括号/标签匹配</li><li>导入检查</li><li>安全扫描（XSS 风险）</li><li>列表渲染 key 属性</li><li>组件库 API 正确性</li></ul><hr><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D2C/</span></span>
<span class="line"><span>├── apps/</span></span>
<span class="line"><span>│   ├── web/                    # 前端 (Next.js 14)</span></span>
<span class="line"><span>│   │   ├── app/(dashboard)/</span></span>
<span class="line"><span>│   │   │   ├── agent/          # Agent 流水线页面</span></span>
<span class="line"><span>│   │   │   ├── figma2code/     # Figma 导入页面</span></span>
<span class="line"><span>│   │   │   └── knowledge/      # 知识库管理页面</span></span>
<span class="line"><span>│   │   └── components/</span></span>
<span class="line"><span>│   │       ├── agent/          # Agent 步骤可视化</span></span>
<span class="line"><span>│   │       └── figma/          # Figma 导入 + 代码预览</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   ├── server/                 # 后端 (FastAPI)</span></span>
<span class="line"><span>│   │   ├── agents/             # 5个 Agent 实现</span></span>
<span class="line"><span>│   │   │   ├── cleaner.py      # Agent 1: 数据清洗</span></span>
<span class="line"><span>│   │   │   ├── converter.py    # Agent 2: 结构化转换</span></span>
<span class="line"><span>│   │   │   ├── retriever.py    # Agent 3: 知识检索</span></span>
<span class="line"><span>│   │   │   ├── generator.py    # Agent 4: 代码生成</span></span>
<span class="line"><span>│   │   │   ├── validator.py    # Agent 5: 测试验证</span></span>
<span class="line"><span>│   │   │   └── pipeline.py     # 流水线串联</span></span>
<span class="line"><span>│   │   ├── routers/            # API 路由</span></span>
<span class="line"><span>│   │   └── services/           # 基础设施</span></span>
<span class="line"><span>│   │       ├── chroma.py       # ChromaDB 客户端</span></span>
<span class="line"><span>│   │       └── llm.py          # LLM 客户端</span></span>
<span class="line"><span>│   │</span></span>
<span class="line"><span>│   └── agent/                  # RAG Worker (端口 8081)</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└── docs/                       # 项目文档</span></span></code></pre></div><hr><h2 id="支持的框架和组件库" tabindex="-1">支持的框架和组件库 <a class="header-anchor" href="#支持的框架和组件库" aria-label="Permalink to &quot;支持的框架和组件库&quot;">​</a></h2><p><strong>框架</strong>：</p><ul><li>React</li><li>Vue 2</li><li>Next.js</li></ul><p><strong>组件库</strong>：</p><ul><li>Element Plus</li><li>Ant Design</li><li>shadcn/ui</li></ul><hr><h2 id="api-接口" tabindex="-1">API 接口 <a class="header-anchor" href="#api-接口" aria-label="Permalink to &quot;API 接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>POST</td><td><code>/api/pipeline/run</code></td><td>运行完整 5 Agent 流水线</td></tr><tr><td>POST</td><td><code>/api/agent/run</code></td><td>单独运行某个 Agent（调试）</td></tr><tr><td>POST</td><td><code>/api/rag/upload</code></td><td>上传文档到知识库</td></tr><tr><td>POST</td><td><code>/api/rag/search</code></td><td>搜索知识库</td></tr><tr><td>GET</td><td><code>/health</code></td><td>服务健康检查</td></tr></tbody></table><hr><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>注册 <a href="https://siliconflow.cn" target="_blank" rel="noreferrer">SiliconFlow</a> 获取 API Key</li><li>编辑 <code>apps/server/.env</code>，填入 Key</li><li>双击 <code>start-all.bat</code> 启动全部服务</li><li>浏览器打开 <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a></li></ol><hr><h2 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h2><ol><li><strong>确定性优先</strong>：非生成任务使用纯算法处理，LLM 仅用于代码生成</li><li><strong>契约驱动通信</strong>：所有 Agent 间通信通过结构化 DSL 进行</li><li><strong>可观测性</strong>：每次流水线执行都可追踪，包含步骤级粒度</li><li><strong>框架无关核心</strong>：流水线引擎与框架无关，框架特定逻辑隔离在代码生成层</li><li><strong>故障安全设计</strong>：单个 Agent 失败被隔离，流水线继续执行</li></ol><hr><h2 id="项目位置" tabindex="-1">项目位置 <a class="header-anchor" href="#项目位置" aria-label="Permalink to &quot;项目位置&quot;">​</a></h2><p>本地路径：<code>E:\\interview\\D2C</code></p>`,57)])])}const b=t(l,[["render",i]]);export{g as __pageData,b as default};
